from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    grid = raw["grid"]
    acc = _accumulate(raw["observations"], grid["cell_size"], grid["width"], grid["height"])
    return _present(acc, grid["width"], grid["height"], raw["fill_value"])


def _validate_input(raw: object) -> str | None:
    return (
        _check_structure(raw)
        or _check_grid(raw)
        or _check_value(raw)
        or _check_observations(raw)
    )


def _check_structure(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if any(k not in raw for k in ("grid", "observations", "fill_value")):
        return "missing field"
    return None


def _check_grid(raw: dict) -> str | None:
    grid = raw["grid"]
    if not isinstance(grid, dict) or any(k not in grid for k in ("width", "height", "cell_size")):
        return "bad grid"
    if not _range_check(grid["width"], 1, MAX_DIM):
        return "bad width"
    if not _range_check(grid["height"], 1, MAX_DIM):
        return "bad height"
    if not _range_check(grid["cell_size"], 1, None):
        return "bad cell size"
    return None


def _check_value(raw: dict) -> str | None:
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    return None


def _check_observations(raw: dict) -> str | None:
    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"
    for obs in observations:
        if not _valid_observation(obs):
            return "bad observation"
    return None


def _range_check(value: object, low: int, high: int | None) -> bool:
    return isinstance(value, int) and value >= low and (high is None or value <= high)


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    if any(k not in obs or not isinstance(obs[k], int) for k in ("x", "y", "value", "quality")):
        return False
    return 0 <= obs["quality"] <= 100


def _accumulate(observations: list, cell_size: int, width: int, height: int) -> dict:
    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue
        col = _project(obs["x"], cell_size, width, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _project(obs["y"], cell_size, height, tolerance)
        if row is None:
            dropped = dropped + 1
            continue
        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    return {
        "sums": sums,
        "counts": counts,
        "degraded": degraded,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
    }


def _project(value: int, cell_size: int, dim: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    idx = value // cell_size
    if idx >= dim:
        if value - dim * cell_size < tolerance:
            idx = dim - 1
        else:
            return None
    return idx


def _present(acc: dict, width: int, height: int, fill_value: int) -> dict:
    counts = acc["counts"]
    coverage = _coverage(counts, width, height)
    return {
        "ok": True,
        "cells": _averaged_rows(acc["sums"], counts, width, height, fill_value),
        "flags": _flag_rows(counts, acc["degraded"], width, height),
        "dropped": acc["dropped"],
        "rejected": acc["rejected"],
        "saturated": acc["saturated"],
        "coverage": coverage,
        "line": _summary_line(width * height, len(counts), acc["dropped"],
                              acc["rejected"], acc["saturated"], coverage),
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

