            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {
            "ok": True,
            "status": new_status,
            "fee": fee,
            "receipt": _receipt(payment, member, new_status, fee),
        }

    if status == "suspended":
        if _tier_error(member["tier"]):
            return {"ok": False, "error": "unknown tier"}
        if "strikes" not in member or (
            not isinstance(member["strikes"], int) or member["strikes"] < 0
        ):
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        for error in (
            _amount_error(payment["amount"]),
            _method_error(payment["method"]),
        ):
            if error:
                return {"ok": False, "error": error}
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {
            "ok": True,
            "status": "reactivated",
            "fee": fee,
            "receipt": _receipt(payment, member, "reactivated", fee),
        }

    return {"ok": False, "error": "unknown status"}

