GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

ACTIVE = "active"
LAPSED = "lapsed"
SUSPENDED = "suspended"
BANNED = "banned"
KNOWN_STATUSES = frozenset((ACTIVE, LAPSED, SUSPENDED))


def _tier_ok(member: dict) -> bool:
    return member["tier"] in TIER_FEES


def _amount_ok(payment: dict) -> bool:
    return isinstance(payment["amount"], int) and payment["amount"] > 0


def _method_ok(payment: dict) -> bool:
    return payment["method"] in ("card", "transfer")


def _expiry_ok(member: dict) -> bool:
    return (
        "expired_days" in member
        and isinstance(member["expired_days"], int)
        and member["expired_days"] >= 0
    )


def _strikes_ok(member: dict) -> bool:
    return (
        "strikes" in member
        and isinstance(member["strikes"], int)
        and member["strikes"] >= 0
    )


def _plan_renewal(status: str, member: dict) -> tuple[str, int]:
    base = TIER_FEES[member["tier"]]
    if status == ACTIVE:
        return "renewed", base
    if status == LAPSED:
        if member["expired_days"] <= GRACE_DAYS:
            return "renewed", base + LATE_FEE
        return "reinstated", base + REINSTATE_SURCHARGE
    return "reactivated", base + base // 2


def _receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment

    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or not member["id"]:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == BANNED:
        return {"ok": False, "error": "member banned"}
    if status not in KNOWN_STATUSES:
        return {"ok": False, "error": "unknown status"}

    if not _tier_ok(member):
        return {"ok": False, "error": "unknown tier"}

    if status == LAPSED and not _expiry_ok(member):
        return {"ok": False, "error": "bad expiry"}
    if status == SUSPENDED:
        if not _strikes_ok(member):
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}

    if not _amount_ok(payment):
        return {"ok": False, "error": "bad amount"}
    if not _method_ok(payment):
        return {"ok": False, "error": "unsupported method"}

    new_status, fee = _plan_renewal(status, member)
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], new_status, fee),
    }

