_VALID_TIERS = frozenset(TIER_FEES)
_VALID_METHODS = frozenset({"card", "transfer"})


def _top_level_error(raw_member: object, raw_payment: object) -> str | None:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return "malformed input"
    if "id" not in raw_member or "status" not in raw_member or "tier" not in raw_member:
        return "missing member field"
    if "amount" not in raw_payment or "method" not in raw_payment:
        return "missing payment field"
    if not isinstance(raw_member["id"], str) or len(raw_member["id"]) == 0:
        return "bad member id"
    return None


def _valid_amount(amount: object) -> bool:
    return isinstance(amount, int) and amount > 0


def _valid_method(method: object) -> bool:
    return method in _VALID_METHODS


def _payment_error(payment: dict) -> str | None:
    if not _valid_amount(payment["amount"]):
        return "bad amount"
    if not _valid_method(payment["method"]):
        return "unsupported method"
    return None


def _active_fee(member: dict) -> tuple[int, str] | str:
    return TIER_FEES[member["tier"]], "renewed"


def _lapsed_fee(member: dict) -> tuple[int, str] | str:
    tier = member["tier"]
    if not isinstance(member.get("expired_days"), int) or member["expired_days"] < 0:
        return "bad expiry"
    if member["expired_days"] <= GRACE_DAYS:
        return TIER_FEES[tier] + LATE_FEE, "renewed"
    return TIER_FEES[tier] + REINSTATE_SURCHARGE, "reinstated"


def _suspended_fee(member: dict) -> tuple[int, str] | str:
    tier = member["tier"]
    if not isinstance(member.get("strikes"), int) or member["strikes"] < 0:
        return "bad strikes"
    if member["strikes"] >= MAX_STRIKES:
        return "too many strikes"
    return TIER_FEES[tier] + TIER_FEES[tier] // 2, "reactivated"


def _make_receipt(method: str, member_id: str, new_status: str, fee: int) -> str:
    return f"{method}:{member_id}:{new_status}:{fee}"


Plan = Callable[[dict], tuple[int, str] | str]


def _handle(member: dict, payment: dict, plan_fn: Plan) -> dict:
    if member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    plan = plan_fn(member)
    if isinstance(plan, str):
        return {"ok": False, "error": plan}
    fee, new_status = plan
    error = _payment_error(payment)
    if error is not None:
        return {"ok": False, "error": error}
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _make_receipt(payment["method"], member["id"], new_status, fee),
    }


_FEE_PLANS = {
    "active": _active_fee,
    "lapsed": _lapsed_fee,
    "suspended": _suspended_fee,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _top_level_error(raw_member, raw_payment)
    if error is not None:
        return {"ok": False, "error": error}

    member = raw_member
    payment = raw_payment

    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}

    plan_fn = _FEE_PLANS.get(member["status"])
    if plan_fn is None:
        return {"ok": False, "error": "unknown status"}

    return _handle(member, payment, plan_fn)

