GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}


def _valid_tier(tier: str) -> bool:
    return tier == "basic" or tier == "gold"


def _valid_amount(amount: object) -> bool:
    return isinstance(amount, int) and amount > 0


def _valid_method(method: str) -> bool:
    return method == "card" or method == "transfer"


def _unknown_tier() -> dict:
    return {"ok": False, "error": "unknown tier"}


def _bad_amount() -> dict:
    return {"ok": False, "error": "bad amount"}


def _bad_method() -> dict:
    return {"ok": False, "error": "unsupported method"}


def _insufficient(payment: dict, fee: int) -> dict | None:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return None


def _receipt(method: str, member_id: str, event: str, fee: int) -> str:
    return f"{method}:{member_id}:{event}:{fee}"


def _renew(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _unknown_tier()
    if not _valid_amount(payment["amount"]):
        return _bad_amount()
    if not _valid_method(payment["method"]):
        return _bad_method()
    fee = TIER_FEES[member["tier"]]
    error = _insufficient(payment, fee)
    if error:
        return error
    return {
        "ok": True,
        "status": "renewed",
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], "renewed", fee),
    }


def _recover(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _unknown_tier()
    expired_days = member.get("expired_days")
    if not isinstance(expired_days, int) or expired_days < 0:
        return {"ok": False, "error": "bad expiry"}
    if not _valid_amount(payment["amount"]):
        return _bad_amount()
    if not _valid_method(payment["method"]):
        return _bad_method()
    if expired_days <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        new_status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        new_status = "reinstated"
    error = _insufficient(payment, fee)
    if error:
        return error
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], new_status, fee),
    }


def _reactivate(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _unknown_tier()
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return {"ok": False, "error": "bad strikes"}
    if strikes >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    if not _valid_amount(payment["amount"]):
        return _bad_amount()
    if not _valid_method(payment["method"]):
        return _bad_method()
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    error = _insufficient(payment, fee)
    if error:
        return error
    return {
        "ok": True,
        "status": "reactivated",
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], "reactivated", fee),
    }


def _banned(member: dict, payment: dict) -> dict:
    return {"ok": False, "error": "member banned"}


def _handlers() -> dict:
    return {
        "active": _renew,
        "lapsed": _recover,
        "suspended": _reactivate,
        "banned": _banned,
