def _malformed_input(raw_member: object, raw_payment: object) -> dict | None:
    member = isinstance(raw_member, dict)
    payment = isinstance(raw_payment, dict)
    if not member or not payment:
        return {"ok": False, "error": "malformed input"}
    error = _missing_member_field(raw_member) or _missing_payment_field(raw_payment)
    if error is not None:
        return error
