def _missing_member_field(member: dict) -> dict | None:
    if (
        "id" not in member
        or "status" not in member
        or "tier" not in member
    ):
        return {"ok": False, "error": "missing member field"}
    return None


def _missing_payment_field(payment: dict) -> dict | None:
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    return None


def _invalid_status(member: dict) -> bool:
    status = member.get("status")
    return status == "banned" or status not in ("active", "lapsed", "suspended")


def _invalid_tier(member: dict) -> bool:
    return member.get("tier") not in VALID_TIERS


def _payment_error(payment: dict) -> dict | None:
    amount = payment["amount"]
    if not isinstance(amount, int) or amount <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    return None


def _insufficient(payment: dict, fee: int) -> dict | None:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return None


def _success(member: dict, payment: dict, outcome: str, fee: int) -> dict:
    return {
        "ok": True,
        "status": outcome,
        "fee": fee,
        "receipt": f'{payment["method"]}:{member["id"]}:{outcome}:{fee}',
    }


def _renew_active(member: dict, payment: dict) -> dict:
    error = _payment_error(payment)
    if error is not None:
        return error
    fee = TIER_FEES[member["tier"]]
    error = _insufficient(payment, fee)
    if error is not None:
        return error
    return _success(member, payment, "renewed", fee)


def _renew_lapsed(member: dict, payment: dict) -> dict:
    expired_days = member.get("expired_days", -1)
    if not isinstance(expired_days, int) or expired_days < 0:
        return {"ok": False, "error": "bad expiry"}
    error = _payment_error(payment)
    if error is not None:
        return error
    if expired_days <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        outcome = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        outcome = "reinstated"
    error = _insufficient(payment, fee)
    if error is not None:
        return error
    return _success(member, payment, outcome, fee)


def _reactivate_suspended(member: dict, payment: dict) -> dict:
    strikes = member.get("strikes", -1)
    if not isinstance(strikes, int) or strikes < 0:
        return {"ok": False, "error": "bad strikes"}
    if strikes >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    error = _payment_error(payment)
    if error is not None:
        return error
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    error = _insufficient(payment, fee)
    if error is not None:
        return error
    return _success(member, payment, "reactivated", fee)


_DISPATCH = {
    "active": _renew_active,
    "lapsed": _renew_lapsed,
    "suspended": _reactivate_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _malformed_input(raw_member, raw_payment)
    if error is not None:
        return error
    member = raw_member
    payment = raw_payment

    if _invalid_status(member):
        action = "member banned" if member["status"] == "banned" else "unknown status"
        return {"ok": False, "error": action}
    if _invalid_tier(member):
        return {"ok": False, "error": "unknown tier"}

    handler = _DISPATCH[member["status"]]
    return handler(member, payment)

