from __future__ import annotations


def password_strength(pw: str) -> int:
    length = len(pw)
    score = 0

    if length >= 8:
        score += 1
    elif length < 4:
        score -= 1

    has_lower = any(ch.islower() for ch in pw)
    has_upper = any(ch.isupper() for ch in pw)
    has_digit = any(ch.isdigit() for ch in pw)
    has_symbol = any(not ch.isalnum() for ch in pw)

    score += has_lower + has_upper + has_digit + has_symbol

    repeats = 0
    previous: str | None = None
    for ch in pw:
        if ch == previous:
            repeats += 1
        previous = ch

    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if length >= 12 and has_symbol:
        score += 1

    return max(score, 0)

from __future__ import annotations


def _diversity(pw: str) -> int:
    return sum(
        (
            any(ch.islower() for ch in pw),
            any(ch.isupper() for ch in pw),
            any(ch.isdigit() for ch in pw),
            any(not ch.isalnum() for ch in pw),
        )
    )


def _length_points(pw: str) -> int:
    if len(pw) >= 8:
        return 1
    if len(pw) < 4:
        return -1
    return 0


def _repeat_points(pw: str) -> int:
    repeats = sum(pw[i] == pw[i - 1] for i in range(1, len(pw)))
    if repeats >= 3:
        return 2
    if repeats >= 1:
        return 1
    return 0


def _symbol_bonus(pw: str) -> int:
    if len(pw) >= 12 and any(not ch.isalnum() for ch in pw):
        return 1
    return 0


def password_strength(pw: str) -> int:
    score = (
        _diversity(pw)
        + _length_points(pw)
        - _repeat_points(pw)
        + _symbol_bonus(pw)
    )
    return max(score, 0)

