def _bad_id(member: dict, payment: dict) -> str | None:
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return None


def _banned(member: dict, payment: dict) -> str | None:
    if member["status"] == "banned":
        return "member banned"
    return None


def _basic_error(raw_member: object, raw_payment: object) -> str | None:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return "malformed input"
    member, payment = raw_member, raw_payment
    for check in (_missing_member, _missing_payment, _bad_id, _banned):
        error = check(member, payment)
        if error is not None:
            return error
    return None


def _valid_tier(tier: object) -> bool:
    if isinstance(tier, str) and tier in TIER_FEES:
        return True
    return False


def _valid_amount(amount: object) -> bool:
    if isinstance(amount, int) and amount > 0:
        return True
    return False


def _valid_method(method: object) -> bool:
    if isinstance(method, str) and method in VALID_METHODS:
        return True
    return False


def _active(member: dict, tier_fee: int) -> tuple[int, str]:
    return (tier_fee, "renewed")


def _lapsed(member: dict, tier_fee: int) -> tuple[int, str]:
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
        raise ValueError("bad expiry")
    if member["expired_days"] <= GRACE_DAYS:
        return (tier_fee + LATE_FEE, "renewed")
    return (tier_fee + REINSTATE_SURCHARGE, "reinstated")


def _suspended(member: dict, tier_fee: int) -> tuple[int, str]:
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        raise ValueError("bad strikes")
    if member["strikes"] >= MAX_STRIKES:
        raise ValueError("too many strikes")
    return (tier_fee + tier_fee // 2, "reactivated")


_POLICIES = {
    "active": _active,
    "lapsed": _lapsed,
    "suspended": _suspended,
}


def _receipt(method: str, member_id: str, action: str, fee: int) -> str:
    return f"{method}:{member_id}:{action}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _basic_error(raw_member, raw_payment)
    if error is not None:
        return {"ok": False, "error": error}

    member, payment = raw_member, raw_payment
    policy = _POLICIES.get(member["status"])
    if policy is None:
        return {"ok": False, "error": "unknown status"}
    if not _valid_tier(member["tier"]):
        return {"ok": False, "error": "unknown tier"}

    try:
        fee, action = policy(member, TIER_FEES[member["tier"]])
    except ValueError as exc:
        return {"ok": False, "error": str(exc)}

    if not _valid_amount(payment["amount"]):
        return {"ok": False, "error": "bad amount"}
    if not _valid_method(payment["method"]):
        return {"ok": False, "error": "unsupported method"}
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    return {
        "ok": True,
        "status": action,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], action, fee),
    }

