from __future__ import annotations

_MIN_LENGTH = 8
_SHORT_LENGTH = 4
_REPEAT_MILD = 1
_REPEAT_THRESHOLD = 3
_LONG_LENGTH = 12

_LENGTH_SCORE = 1
_TOO_SHORT_PENALTY = -1
_CHAR_CLASS_SCORE = 1
_REPEAT_HEAVY_PENALTY = -2
_REPEAT_MILD_PENALTY = -1
_LONG_WITH_SYMBOL_REWARD = 1
_MIN_SCORE = 0


def password_strength(pw: str) -> int:
    return max(
        _length_bonus(len(pw))
        + _character_class_score(pw)
        + _repeat_penalty(pw)
        + _symbol_reward(pw),
        _MIN_SCORE,
    )


def _length_bonus(length: int) -> int:
    if length >= _MIN_LENGTH:
        return _LENGTH_SCORE
    if length < _SHORT_LENGTH:
        return _TOO_SHORT_PENALTY
    return 0


def _character_class_score(pw: str) -> int:
    classes = (
        any(ch.islower() for ch in pw),
        any(ch.isupper() for ch in pw),
        any(ch.isdigit() for ch in pw),
        any(not ch.isalnum() for ch in pw),
    )
    return _CHAR_CLASS_SCORE * sum(classes)


def _repeat_penalty(pw: str) -> int:
    repeats = sum(pw[i] == pw[i - 1] for i in range(1, len(pw)))
    if repeats >= _REPEAT_THRESHOLD:
        return _REPEAT_HEAVY_PENALTY
    if repeats >= _REPEAT_MILD:
