def _length_points(pw: str) -> int:
    if len(pw) >= 8:
        return 1
    if len(pw) < 4:
        return -1
    return 0


def _class_points(pw: str) -> int:
    return (
        int(any(ch.islower() for ch in pw))
        + int(any(ch.isupper() for ch in pw))
        + int(any(ch.isdigit() for ch in pw))
        + int(any(not ch.isalnum() for ch in pw))
    )


def _repeats_points(pw: str) -> int:
    repeats = sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])
    if repeats >= 3:
        return -2
    if repeats >= 1:
        return -1
    return 0


def _bonus_points(pw: str) -> int:
    if len(pw) >= 12 and any(not ch.isalnum() for ch in pw):
        return 1
    return 0


def password_strength(pw: str) -> int:
    points = (
        _length_points(pw)
        + _class_points(pw)
        + _repeats_points(pw)
        + _bonus_points(pw)
    )
    return max(points, 0)

