export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Req = Record<string, unknown>;

interface CategorySpec {
  base: number;
  highAdd: number;
  maxNights: number;
  maxGuests: number;
  minNights?: number;
  guestSurcharge?: number;
  fixedSurcharge?: number;
}

const isInt = (v: unknown, min: number, max: number): boolean =>
  typeof v === "number" && Number.isInteger(v) && v >= min && v <= max;

const isSeason = (v: unknown): boolean => v === "low" || v === "high";

const asNumber = (v: unknown): number => v as number;

const CATEGORIES: Record<string, CategorySpec> = {
  standard: { base: 80, highAdd: 30, maxNights: 14, maxGuests: 2 },
  suite: { base: 150, highAdd: 60, maxNights: 21, maxGuests: 4, guestSurcharge: 25 },
  villa: { base: 300, highAdd: 120, maxNights: 28, maxGuests: 8, minNights: 3, fixedSurcharge: 500 },
};

function flexibleDiscount(req: Req, total: number): number {
  return req.coupon === "VIP" || asNumber(req.loyaltyYears) > 2
    ? total - Math.floor(total / 10)
    : total;
}

function policyFor(req: Req): string {
  return req.coupon === "VIP" || asNumber(req.loyaltyYears) > 2 ? "flex" : "strict";
}

function parseRequest(raw: unknown): { req: Req } | QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Req;
  if (!Number.isInteger(req.loyaltyYears) || asNumber(req.loyaltyYears) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return { req };
}

function categorySpec(category: unknown): CategorySpec | undefined {
  return CATEGORIES[category as string];
}

function validateRequest(req: Req, spec: CategorySpec): QuoteResult | null {
  if (!isInt(req.nights, 1, spec.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minNights && asNumber(req.nights) < spec.minNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!isInt(req.guests, 1, spec.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  return null;
}

function priceRequest(req: Req, spec: CategorySpec, category: string): QuoteResult {
  const nights = asNumber(req.nights);
  let total = spec.base * nights;
  if (req.season === "high") {
    total += spec.highAdd * nights;
  }
  total = flexibleDiscount(req, total);

  if (category === "suite" && asNumber(req.guests) > 2) {
    total += spec.guestSurcharge!;
  } else if (spec.fixedSurcharge) {
    total += spec.fixedSurcharge;
  }

  const policy = policyFor(req);
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!("req" in parsed)) {
    return parsed;
  }
  const { req } = parsed;

  const spec = categorySpec(req.category);
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const invalid = validateRequest(req, spec);
  if (invalid) {
    return invalid;
  }

  return priceRequest(req, spec, req.category as string);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";

interface ParsedRequest {
  category: Category;
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: string;
  coupon?: string;
}

interface CategoryRule {
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highSurcharge: number;
  minStay?: number;
  flatFee?: number;
  largeGuestExtra?: number;
}

type ParseResult = { ok: true; value: ParsedRequest } | { ok: false; error: string };
type ValidateResult = { ok: true } | { ok: false; error: string };

const DISCOUNT_THRESHOLD = 3;

const RULES: Record<Category, CategoryRule> = {
  standard: { minNights: 1, maxNights: 14, minGuests: 1, maxGuests: 2, baseRate: 80, highSurcharge: 30 },
  suite: { minNights: 1, maxNights: 21, minGuests: 1, maxGuests: 4, baseRate: 150, highSurcharge: 60, largeGuestExtra: 25 },
  villa: { minNights: 1, maxNights: 28, minGuests: 1, maxGuests: 8, baseRate: 300, highSurcharge: 120, minStay: 3, flatFee: 500 },
};

function ok(total: number, policy: string, category: Category, nights: number): QuoteResult {
  return { ok: true, total, policy, line: `${category}:${nights}n:${total}:${policy}` };
}

function fail(error: string): QuoteResult {
  return { ok: false, error };
}

function inRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function inSeason(value: unknown): boolean {
  return value === "low" || value === "high";
}

function eligible(loyaltyYears: number, coupon?: string): boolean {
  return loyaltyYears >= DISCOUNT_THRESHOLD || coupon === "VIP";
}

function validate(category: Category, req: ParsedRequest): ValidateResult {
  const rule = RULES[category];
  if (!inRange(req.nights, rule.minNights, rule.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (rule.minStay !== undefined && req.nights < rule.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!inRange(req.guests, rule.minGuests, rule.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (!inSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  return { ok: true };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return fail("malformed request");
  }
  const req = raw as Record<string, unknown>;

  if (!inRange(req.loyaltyYears, 0, Number.MAX_SAFE_INTEGER)) {
    return fail("bad loyalty");
  }

  const category = req.category;
  if (category !== "standard" && category !== "suite" && category !== "villa") {
    return fail("unknown category");
  }

  const parsed: ParsedRequest = {
    category,
    loyaltyYears: req.loyaltyYears as number,
    nights: req.nights as number,
    guests: req.guests as number,
    season: req.season as string,
    coupon: req.coupon as string | undefined,
  };

  const validation = validate(category, parsed);
  if (!validation.ok) {
    return fail(validation.error);
  }

  const rule = RULES[category];
  const preferred = eligible(parsed.loyaltyYears, parsed.coupon);

  let total = rule.baseRate * parsed.nights;
  total += (parsed.season === "high" ? rule.highSurcharge : 0) * parsed.nights;
  total = preferred ? total - Math.floor(total / 10) : total;
  total += (rule.largeGuestExtra !== undefined && parsed.guests > 2 ? rule.largeGuestExtra : 0);
  total += rule.flatFee ?? 0;

  return ok(total, preferred ? "flex" : "strict", category, parsed.nights);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  minNights: number;
  maxNights: number;
  minStay: number;
  maxGuests: number;
  basePerNight: number;
  highPerNight: number;
  extraFee: (nights: number, guests: number) => number;
  discounted: (loyaltyYears: number, coupon?: string) => boolean;
  flexible: (loyaltyYears: number, coupon?: string) => boolean;
}

const isVIP = (coupon?: string) => coupon === "VIP";

const applyDiscount = (total: number) => total - Math.floor(total / 10);

const STANDARD: CategoryConfig = {
  name: "standard",
  minNights: 1,
  maxNights: 14,
  minStay: 1,
  maxGuests: 2,
  basePerNight: 80,
  highPerNight: 30,
  extraFee: () => 0,
  discounted: (loyaltyYears, coupon) => loyaltyYears >= 3 || isVIP(coupon),
  flexible: (loyaltyYears, coupon) => isVIP(coupon) || loyaltyYears > 2,
};

const SUITE: CategoryConfig = {
  name: "suite",
  minNights: 1,
  maxNights: 21,
  minStay: 1,
  maxGuests: 4,
  basePerNight: 150,
  highPerNight: 60,
  extraFee: (_nights, guests) => (guests > 2 ? 25 : 0),
  discounted: (loyaltyYears, coupon) => isVIP(coupon) || loyaltyYears >= 3,
  flexible: (loyaltyYears, coupon) => isVIP(coupon) || loyaltyYears >= 3,
};

const VILLA: CategoryConfig = {
  name: "villa",
  minNights: 1,
  maxNights: 28,
  minStay: 3,
  maxGuests: 8,
  basePerNight: 300,
  highPerNight: 120,
  extraFee: () => 500,
  discounted: (loyaltyYears, coupon) => loyaltyYears > 2 || isVIP(coupon),
  flexible: (loyaltyYears, coupon) => isVIP(coupon) || loyaltyYears >= 3,
};

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: STANDARD,
  suite: SUITE,
  villa: VILLA,
};

const badCategory = (name: string, value: unknown): boolean =>
  value !== "low" && value !== "high";

function validate(
  cfg: CategoryConfig,
  nights: number,
  guests: number,
  season: string
): string | null {
  const rules: Array<{ check: boolean; message: string }> = [
    { check: !Number.isInteger(nights) || nights < cfg.minNights || nights > cfg.maxNights, message: "bad nights" },
    { check: nights < cfg.minStay, message: "villa minimum stay" },
    { check: !Number.isInteger(guests) || guests < 1 || guests > cfg.maxGuests, message: "bad guests" },
    { check: badCategory(cfg.name, season), message: "bad season" },
  ];
  return rules.find((rule) => rule.check)?.message ?? null;
}

function totalFor(
  cfg: CategoryConfig,
  nights: number,
  guests: number,
  season: string,
  loyaltyYears: number,
  coupon?: string
): number {
  const base = nights * cfg.basePerNight;
  const seasonal = season === "high" ? nights * cfg.highPerNight : 0;
  const discounted = cfg.discounted(loyaltyYears, coupon) ? applyDiscount(base + seasonal) : base + seasonal;
  return discounted + cfg.extraFee(nights, guests);
}

function quoteFor(
  cfg: CategoryConfig,
  req: Record<string, unknown>,
  loyaltyYears: number,
  coupon?: string
): QuoteResult {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  const invalid = validate(cfg, nights, guests, season);
  if (invalid) {
    return { ok: false, error: invalid };
  }

  const total = totalFor(cfg, nights, guests, season, loyaltyYears, coupon);
  const policy = cfg.flexible(loyaltyYears, coupon) ? "flex" : "strict";
  const line = `${cfg.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  return quoteFor(config, req, req.loyaltyYears as number, req.coupon as string | undefined);
}

