export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventHandler {
  status: "ok" | "error";
  format: (payload: EventPayload) => string;
}

const HANDLERS: Record<string, EventHandler> = {
  "user.created": { status: "ok", format: (p) => `created user ${String(p.data.id)}` },
  "user.updated": { status: "ok", format: (p) => `updated user ${String(p.data.id)}` },
  "user.deleted": { status: "ok", format: (p) => `deleted user ${String(p.data.id)}` },
  "order.placed": { status: "ok", format: (p) => `order placed ${String(p.data.orderId)}` },
  "order.cancelled": { status: "ok", format: (p) => `order cancelled ${String(p.data.orderId)}` },
  "order.shipped": { status: "ok", format: (p) => `order shipped ${String(p.data.orderId)}` },
  "payment.succeeded": { status: "ok", format: (p) => `payment succeeded ${String(p.data.paymentId)}` },
  "payment.failed": { status: "error", format: (p) => `payment failed ${String(p.data.paymentId)}` },
  "invoice.issued": { status: "ok", format: (p) => `invoice issued ${String(p.data.invoiceId)}` },
  "invoice.voided": { status: "ok", format: (p) => `invoice voided ${String(p.data.invoiceId)}` },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const handler = HANDLERS[name];
  if (!handler) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  return { status: handler.status, message: handler.format(payload) };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

type Handler = (data: Record<string, unknown>) => EventResult;

const ok = (message: string): EventResult => ({ status: "ok", message });

const handlers: Record<string, Handler> = {
