export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Season = "low" | "high";

interface CategoryConfig {
  label: string;
  baseRate: number;
  highExtra: number;
  maxNights: number;
  minNights?: number;
  minStayError?: string;
  maxGuests: number;
  extraGuestsFee?: number;
  flatFee?: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { label: "standard", baseRate: 80,  highExtra: 30, maxNights: 14, maxGuests: 2 },
  suite:    { label: "suite",    baseRate: 150, highExtra: 60, maxNights: 21, maxGuests: 4, extraGuestsFee: 25 },
  villa:    { label: "villa",    baseRate: 300, highExtra: 120, maxNights: 28, minNights: 3, minStayError: "villa minimum stay", maxGuests: 8, flatFee: 500 },
};

function isNonNegativeInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 0;
}

function isSeason(value: unknown): value is Season {
  return value === "low" || value === "high";
}

function nightsError(req: Record<string, unknown>, config: CategoryConfig): string | null {
  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > config.maxNights) {
    return "bad nights";
  }
  return null;
}

function minStayError(nights: number, config: CategoryConfig): string | null {
  if (config.minStayError !== undefined && nights < (config.minNights as number)) {
    return config.minStayError;
  }
  return null;
}

function guestsError(req: Record<string, unknown>, config: CategoryConfig): string | null {
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > config.maxGuests) {
    return "bad guests";
  }
  return null;
}

function seasonError(req: Record<string, unknown>): string | null {
  if (!isSeason(req.season)) {
    return "bad season";
  }
  return null;
}

function firstError(errors: Array<string | null>): string | null {
  for (const error of errors) {
    if (error !== null) {
      return error;
    }
  }
  return null;
}

function quoteCategory(
  req: Record<string, unknown>,
  loyaltyYears: number,
  config: CategoryConfig,
): QuoteResult {
  const error = firstError([
    nightsError(req, config),
    minStayError(req.nights as number, config),
    guestsError(req, config),
    seasonError(req),
  ]);
  if (error !== null) {
    return { ok: false, error };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as Season;
  const privileged = req.coupon === "VIP" || loyaltyYears >= 3;

  let total = (config.baseRate + (season === "high" ? config.highExtra : 0)) * nights;
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if (config.extraGuestsFee !== undefined && guests > 2) {
    total += config.extraGuestsFee;
  }
  total += config.flatFee ?? 0;

  const policy = privileged ? "flex" : "strict";
  const line = `${config.label}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isNonNegativeInt(req.loyaltyYears)) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyaltyYears = req.loyaltyYears;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  return quoteCategory(req, loyaltyYears, config);
}

