export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

const eventHandlers: Record<string, (data: Record<string, unknown>) => EventResult> = {
  "user.created": (data) => ({ status: "ok", message: `created user ${String(data.id)}` }),
  "user.updated": (data) => ({ status: "ok", message: `updated user ${String(data.id)}` }),
  "user.deleted": (data) => ({ status: "ok", message: `deleted user ${String(data.id)}` }),
  "order.placed": (data) => ({ status: "ok", message: `order placed ${String(data.orderId)}` }),
  "order.cancelled": (data) => ({ status: "ok", message: `order cancelled ${String(data.orderId)}` }),
  "order.shipped": (data) => ({ status: "ok", message: `order shipped ${String(data.orderId)}` }),
  "payment.succeeded": (data) => ({ status: "ok", message: `payment succeeded ${String(data.paymentId)}` }),
  "payment.failed": (data) => ({ status: "error", message: `payment failed ${String(data.paymentId)}` }),
  "invoice.issued": (data) => ({ status: "ok", message: `invoice issued ${String(data.invoiceId)}` }),
  "invoice.voided": (data) => ({ status: "ok", message: `invoice voided ${String(data.invoiceId)}` }),
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const handler = eventHandlers[name];
  if (handler) {
    return handler(payload.data);
  }
  return { status: "error", message: `unknown event: ${name}` };
}

