  "user.created": (payload) => ({ status: "ok", message: `created user ${String(payload.data.id)}` }),
  "user.updated": (payload) => ({ status: "ok", message: `updated user ${String(payload.data.id)}` }),
  "user.deleted": (payload) => ({ status: "ok", message: `deleted user ${String(payload.data.id)}` }),
