  "order.cancelled": (payload) => ({ status: "ok", message: `order cancelled ${String(payload.data.orderId)}` }),
  "order.shipped": (payload) => ({ status: "ok", message: `order shipped ${String(payload.data.orderId)}` }),
  "payment.succeeded": (payload) => ({ status: "ok", message: `payment succeeded ${String(payload.data.paymentId)}` }),
  "payment.failed": (payload) => ({ status: "error", message: `payment failed ${String(payload.data.paymentId)}` }),
  "invoice.issued": (payload) => ({ status: "ok", message: `invoice issued ${String(payload.data.invoiceId)}` }),
  "invoice.voided": (payload) => ({ status: "ok", message: `invoice voided ${String(payload.data.invoiceId)}` }),
};

