export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  maxGuests: number;
  baseRate: number;
  highSurcharge: number;
  loyaltyForDiscount: number;   // loyaltyYears >= this triggers the 10% discount
  flexibleLoyalty: number;      // loyaltyYears > this makes policy flex
  perGuestFee?: number;         // flat fee added once when guests > 2
  flatFee?: number;             // fee added unconditionally
  minStay?: number;             // inclusive minimum stay
  minStayError?: string;        // custom bad-min-stay message
}

const SPECS: Record<string, CategorySpec> = {
  standard: { maxNights: 14, maxGuests: 2, baseRate: 80,  highSurcharge: 30,  loyaltyForDiscount: 3, flexibleLoyalty: 2 },
  suite:    { maxNights: 21, maxGuests: 4, baseRate: 150, highSurcharge: 60,  loyaltyForDiscount: 3, flexibleLoyalty: 2, perGuestFee: 25 },
  villa:    { maxNights: 28, maxGuests: 8, baseRate: 300, highSurcharge: 120, loyaltyForDiscount: 3, flexibleLoyalty: 2, flatFee: 500, minStay: 3, minStayError: "villa minimum stay" },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const spec = SPECS[req.category as string];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyalty = req.loyaltyYears as number;
  const coupon = req.coupon as string;

  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: spec.minStayError };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = spec.baseRate * nights;
  if (req.season === "high") {
    total += spec.highSurcharge * nights;
  }
  if (coupon === "VIP" || loyalty >= spec.loyaltyForDiscount) {
    total -= Math.floor(total / 10);
  }
  if (spec.perGuestFee !== undefined && guests > 2) {
    total += spec.perGuestFee;
  }
  if (spec.flatFee !== undefined) {
    total += spec.flatFee;
  }

  const policy = coupon === "VIP" || loyalty > spec.flexibleLoyalty ? "flex" : "strict";
  const line = `${req.category}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

