export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function flagValue(argv: string[], flag: string, index: number): string {
  const value = argv[index];
  if (value === undefined) {
    throw new Error(`${flag} requires a path`);
  }
  return value;
}

function flagInt(argv: string[], flag: string, index: number): number {
  const value = Number(argv[index]);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    switch (arg) {
      case "--verbose":
        config.verbose = true;
        break;
      case "--quiet":
        config.quiet = true;
        break;
      case "--dry-run":
        config.dryRun = true;
        break;
      case "--force":
        config.force = true;
        break;
      case "--no-color":
        config.color = false;
        break;
      case "--strict":
        config.strict = true;
        break;
      case "--output":
        config.outputPath = flagValue(argv, "--output", ++i);
        break;
      case "--config":
        config.configPath = flagValue(argv, "--config", ++i);
        break;
      case "--format": {
        const value = argv[++i];
        if (value === undefined || !["json", "yaml", "text"].includes(value)) {
          throw new Error(`unsupported format: ${String(value)}`);
        }
        config.format = value;
        break;
      }
      case "--log-level": {
        const value = argv[++i];
        if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
          throw new Error(`unsupported log level: ${String(value)}`);
        }
        config.logLevel = value;
        break;
      }
      case "--retries":
        config.maxRetries = flagInt(argv, "--retries", ++i);
        break;
      case "--timeout":
        config.timeoutMs = flagInt(argv, "--timeout", ++i);
        break;
      case "--parallel":
        config.parallelism = flagInt(argv, "--parallel", ++i);
        break;
      default:
        throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
