export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

type Handler = (data: EventPayload["data"]) => EventResult;

function user(id: unknown, verb: string): EventResult {
  return { status: "ok", message: `${verb} user ${String(id)}` };
}

function order(orderId: unknown, verb: string): EventResult {
  return { status: "ok", message: `${verb} order ${String(orderId)}` };
}

function payment(paymentId: unknown, verb: string, ok: boolean): EventResult {
  return { status: ok ? "ok" : "error", message: `${verb} payment ${String(paymentId)}` };
}

function invoice(invoiceId: unknown, verb: string): EventResult {
  return { status: "ok", message: `${verb} invoice ${String(invoiceId)}` };
}

const HANDLERS: Record<string, Handler> = {
  "user.created": (d) => user(d.id, "created"),
  "user.updated": (d) => user(d.id, "updated"),
  "user.deleted": (d) => user(d.id, "deleted"),
  "order.placed": (d) => order(d.orderId, "placed"),
  "order.cancelled": (d) => order(d.orderId, "cancelled"),
  "order.shipped": (d) => order(d.orderId, "shipped"),
  "payment.succeeded": (d) => payment(d.paymentId, "succeeded", true),
  "payment.failed": (d) => payment(d.paymentId, "failed", false),
  "invoice.issued": (d) => invoice(d.invoiceId, "issued"),
  "invoice.voided": (d) => invoice(d.invoiceId, "voided"),
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const handle = HANDLERS[name];
  if (handle) {
    return handle(payload.data);
  }
  return { status: "error", message: `unknown event: ${name}` };
}

