};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

const BOOLEAN_FLAGS: Record<string, (config: FlagConfig) => void> = {
  "--verbose": (config) => {
    config.verbose = true;
  },
  "--quiet": (config) => {
    config.quiet = true;
  },
  "--dry-run": (config) => {
    config.dryRun = true;
  },
  "--force": (config) => {
    config.force = true;
  },
  "--no-color": (config) => {
    config.color = false;
  },
  "--strict": (config) => {
    config.strict = true;
  },
};

type ValueConsumer = (config: FlagConfig, raw: string) => void;

interface ValueFlagSpec {
  apply: ValueConsumer;
  missingMessage?: string;
  isInvalid: (raw: string | undefined) => boolean;
  invalidMessage: (raw: string | undefined) => string;
}

const VALUE_FLAGS: Record<string, ValueFlagSpec> = {
  "--output": {
    apply: (config, raw) => {
      config.outputPath = raw;
    },
    missingMessage: "--output requires a path",
    isInvalid: () => false,
    invalidMessage: () => "",
  },
  "--config": {
    apply: (config, raw) => {
      config.configPath = raw;
    },
    missingMessage: "--config requires a path",
    isInvalid: () => false,
    invalidMessage: () => "",
  },
  "--format": {
    apply: (config, raw) => {
      config.format = raw;
    },
    isInvalid: (raw) => raw !== undefined && !["json", "yaml", "text"].includes(raw),
    invalidMessage: (raw) => `unsupported format: ${String(raw)}`,
  },
  "--log-level": {
    apply: (config, raw) => {
      config.logLevel = raw;
    },
    isInvalid: (raw) => raw !== undefined && !["debug", "info", "warn", "error"].includes(raw),
    invalidMessage: (raw) => `unsupported log level: ${String(raw)}`,
  },
  "--retries": {
    apply: (config, raw) => {
      config.maxRetries = Number(raw);
    },
    isInvalid: (raw) => !Number.isInteger(Number(raw)),
    invalidMessage: () => "--retries must be an integer",
  },
  "--timeout": {
    apply: (config, raw) => {
      config.timeoutMs = Number(raw);
    },
    isInvalid: (raw) => !Number.isInteger(Number(raw)),
    invalidMessage: () => "--timeout must be an integer",
  },
  "--parallel": {
    apply: (config, raw) => {
      config.parallelism = Number(raw);
    },
    isInvalid: (raw) => !Number.isInteger(Number(raw)),
    invalidMessage: () => "--parallel must be an integer",
  },
};

function consumeValueFlag(config: FlagConfig, flag: string, argv: string[], i: number): number {
  const spec = VALUE_FLAGS[flag]!;
  const nextIndex = i + 1;
  const raw = argv[nextIndex];

  if (raw === undefined && spec.missingMessage !== undefined) {
    throw new Error(spec.missingMessage);
  }
  if (raw === undefined || spec.isInvalid(raw)) {
    throw new Error(spec.invalidMessage(raw));
  }
  spec.apply(config, raw);
  return nextIndex;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const booleanApply = BOOLEAN_FLAGS[arg];
    if (booleanApply) {
      booleanApply(config);
      continue;
    }
    if (arg in VALUE_FLAGS) {
      i = consumeValueFlag(config, arg, argv, i);
      continue;
    }
    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

