  return num;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const setBoolean = BOOLEAN_FLAGS[arg];
    if (setBoolean) {
      setBoolean(config);
      continue;
    }

    const setValue = VALUE_FLAGS[arg];
    if (setValue) {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error(`${arg} requires a value`);
      }
      setValue(config, value);
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

type Apply = (config: FlagConfig, value: string | undefined) => void;

const BOOLEAN_FLAGS: Record<string, Apply> = {
  "--verbose": (c) => (c.verbose = true),
  "--quiet": (c) => (c.quiet = true),
  "--dry-run": (c) => (c.dryRun = true),
  "--force": (c) => (c.force = true),
  "--no-color": (c) => (c.color = false),
  "--strict": (c) => (c.strict = true),
};

function requireValue(value: string | undefined, flag: string): string {
  if (value === undefined) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

function requireInteger(value: string | undefined, flag: string): number {
  const parsed = Number(value);
  if (!Number.isInteger(parsed)) {
    throw new Error(`${flag} must be an integer`);
  }
  return parsed;
}

const VALUE_FLAGS: Record<string, Apply> = {
  "--output": (c, v) => (c.outputPath = requireValue(v, "--output")),
  "--config": (c, v) => (c.configPath = requireValue(v, "--config")),
  "--format": (c, v) => {
    const value = requireValue(v, "--format");
    if (!["json", "yaml", "text"].includes(value)) {
      throw new Error(`unsupported format: ${value}`);
    }
    c.format = value;
  },
  "--log-level": (c, v) => {
    const value = requireValue(v, "--log-level");
    if (!["debug", "info", "warn", "error"].includes(value)) {
      throw new Error(`unsupported log level: ${value}`);
    }
    c.logLevel = value;
  },
  "--retries": (c, v) => (c.maxRetries = requireInteger(v, "--retries")),
  "--timeout": (c, v) => (c.timeoutMs = requireInteger(v, "--timeout")),
  "--parallel": (c, v) => (c.parallelism = requireInteger(v, "--parallel")),
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const apply = BOOLEAN_FLAGS[arg] ?? VALUE_FLAGS[arg];
    if (apply === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    const takesValue = arg in VALUE_FLAGS;
    apply(config, takesValue ? argv[++i] : undefined);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

type FlagHandler = (config: FlagConfig, argv: string[], i: number) => number;

function booleanFlag(key: keyof FlagConfig, value = true): FlagHandler {
  return (config) => {
    config[key] = value;
    return 0;
  };
}

function pathFlag(key: "outputPath" | "configPath", flag: string): FlagHandler {
  return (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined) {
      throw new Error(`${flag} requires a path`);
    }
    config[key] = value;
    return 1;
  };
}

const ENUM_VALUES: Record<string, readonly string[]> = {
  "--format": ["json", "yaml", "text"],
  "--log-level": ["debug", "info", "warn", "error"],
};

function choiceFlag(key: "format" | "logLevel", flag: string): FlagHandler {
  return (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined || !ENUM_VALUES[flag]!.includes(value)) {
      throw new Error(`unsupported ${flag.slice(2).replace("-", " ")}: ${String(value)}`);
    }
    config[key] = value;
    return 1;
  };
}

function integerFlag(
  key: "maxRetries" | "timeoutMs" | "parallelism",
  flag: string,
): FlagHandler {
  return (config, argv, i) => {
    const value = Number(argv[i + 1]);
    if (!Number.isInteger(value)) {
      throw new Error(`${flag} must be an integer`);
    }
    config[key] = value;
    return 1;
  };
}

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": booleanFlag("verbose"),
  "--quiet": booleanFlag("quiet"),
  "--dry-run": booleanFlag("dryRun"),
  "--force": booleanFlag("force"),
  "--no-color": booleanFlag("color", false),
  "--strict": booleanFlag("strict"),
  "--output": pathFlag("outputPath", "--output"),
  "--config": pathFlag("configPath", "--config"),
  "--format": choiceFlag("format", "--format"),
  "--log-level": choiceFlag("logLevel", "--log-level"),
  "--retries": integerFlag("maxRetries", "--retries"),
  "--timeout": integerFlag("timeoutMs", "--timeout"),
  "--parallel": integerFlag("parallelism", "--parallel"),
};

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = ALIASES[argv[i]!] ?? argv[i]!;
    const handler = FLAG_HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i += handler(config, argv, i);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

const FORMATS = ["json", "yaml", "text"] as const;
const LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

type ArgHandler = (
  config: FlagConfig,
  argv: string[],
  flag: string,
  index: number,
) => number;

function booleanFlag<K extends keyof FlagConfig>(
  key: K,
  value: FlagConfig[K],
): ArgHandler {
  return (config, _argv, _flag, index) => {
    config[key] = value;
    return index;
  };
}

function integerFlag(
  key: "maxRetries" | "timeoutMs" | "parallelism",
): ArgHandler {
  return (config, argv, flag, index) => {
    const value = Number(argv[index + 1]);
    if (!Number.isInteger(value)) {
      throw new Error(`${flag} must be an integer`);
    }
    config[key] = value;
    return index + 1;
  };
}

function pathFlag(key: "outputPath" | "configPath"): ArgHandler {
  return (config, argv, flag, index) => {
    const value = argv[index + 1];
    if (value === undefined) {
      throw new Error(`${flag} requires a path`);
    }
    config[key] = value;
    return index + 1;
  };
}

function enumFlag<K extends keyof FlagConfig>(
  key: K,
  allowed: readonly string[],
  message: (value: string | undefined) => string,
): ArgHandler {
  return (config, argv, flag, index) => {
    const value = argv[index + 1];
    if (value === undefined || !allowed.includes(value)) {
      throw new Error(message(value));
    }
    config[key] = value as FlagConfig[K];
    return index + 1;
  };
}

const HANDLERS: Record<string, ArgHandler> = {
  "--verbose": booleanFlag("verbose", true),
  "--quiet": booleanFlag("quiet", true),
  "--dry-run": booleanFlag("dryRun", true),
  "--force": booleanFlag("force", true),
  "--no-color": booleanFlag("color", false),
  "--strict": booleanFlag("strict", true),
  "--output": pathFlag("outputPath"),
  "--config": pathFlag("configPath"),
  "--retries": integerFlag("maxRetries"),
  "--timeout": integerFlag("timeoutMs"),
  "--parallel": integerFlag("parallelism"),
  "--format": enumFlag("format", FORMATS, (value) => `unsupported format: ${String(value)}`),
  "--log-level": enumFlag("logLevel", LOG_LEVELS, (value) => `unsupported log level: ${String(value)}`),
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = HANDLERS[arg];
    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i = handler(config, argv, arg, i);
  }

  return config;
}

