export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_THRESHOLDS: ReadonlyArray<readonly [number, string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

const FAILING_LETTER = "F";

const MODIFIER_NONE = "none";
const MODIFIER_HONORS = "honors";
const MODIFIER_ATTENDANCE_FAILURE = "attendance-failure";

const ATTENDANCE_FAILURE_THRESHOLD = 20;
const HONORS_EXTRA_CREDIT = 5;
const HONORS_MIN_SCORE = 90;

function letterForScore(score: number): string {
  for (const [threshold, letter] of GRADE_THRESHOLDS) {
    if (score >= threshold) {
      return letter;
    }
  }
  return FAILING_LETTER;
}

export function gradeReport(record: StudentRecord): GradeReport {
  let letter = letterForScore(record.score);
  let modifier = MODIFIER_NONE;

  if (record.absences > ATTENDANCE_FAILURE_THRESHOLD) {
    letter = FAILING_LETTER;
    modifier = MODIFIER_ATTENDANCE_FAILURE;
  } else if (
    record.extraCredit >= HONORS_EXTRA_CREDIT &&
    record.score >= HONORS_MIN_SCORE
  ) {
    modifier = MODIFIER_HONORS;
  }

  return { letter, modifier };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

export function gradeReport(record: StudentRecord): GradeReport {
  let letter = gradeLetter(record.score);
  let modifier = "none";

  if (record.absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (record.extraCredit >= 5 && record.score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

function gradeLetter(score: number): string {
  if (score >= 97) return "A+";
  if (score >= 93) return "A";
  if (score >= 90) return "A-";
  if (score >= 87) return "B+";
  if (score >= 83) return "B";
  if (score >= 73) return "C";
  if (score >= 60) return "D";
  return "F";
}

