}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

type FlagHandler = (config: FlagConfig, argv: string[], index: number) => number;

const SUPPORTED_FORMATS = ["json", "yaml", "text"];
const SUPPORTED_LOG_LEVELS = ["debug", "info", "warn", "error"];

function booleanHandler(set: (config: FlagConfig) => void): FlagHandler {
  return (config) => {
    set(config);
    return 0;
  };
}

function pathHandler(
  flag: string,
  set: (config: FlagConfig, value: string) => void,
): FlagHandler {
  return (config, argv, index) => {
    const value = argv[index + 1];
    if (value === undefined) {
      throw new Error(`${flag} requires a path`);
    }
    set(config, value);
    return 1;
  };
}

function enumHandler(
  supported: readonly string[],
  message: (value: string | undefined) => string,
  set: (config: FlagConfig, value: string) => void,
): FlagHandler {
  return (config, argv, index) => {
    const value = argv[index + 1];
    if (value === undefined || !supported.includes(value)) {
      throw new Error(message(value));
    }
    set(config, value);
    return 1;
  };
}

function integerHandler(flag: string, set: (config: FlagConfig, value: number) => void): FlagHandler {
  return (config, argv, index) => {
    const value = argv[index + 1];
    if (value === undefined) {
      throw new Error(`${flag} must be an integer`);
    }
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) {
      throw new Error(`${flag} must be an integer`);
    }
    set(config, parsed);
    return 1;
  };
}

const HANDLERS: Record<string, FlagHandler> = {
  "--verbose": booleanHandler((c) => (c.verbose = true)),
  "--quiet": booleanHandler((c) => (c.quiet = true)),
  "--dry-run": booleanHandler((c) => (c.dryRun = true)),
  "--force": booleanHandler((c) => (c.force = true)),
  "--no-color": booleanHandler((c) => (c.color = false)),
  "--strict": booleanHandler((c) => (c.strict = true)),
  "--output": pathHandler("--output", (c, v) => (c.outputPath = v)),
  "--config": pathHandler("--config", (c, v) => (c.configPath = v)),
  "--format": enumHandler(
    SUPPORTED_FORMATS,
    (v) => `unsupported format: ${String(v)}`,
    (c, v) => (c.format = v),
  ),
  "--log-level": enumHandler(
    SUPPORTED_LOG_LEVELS,
    (v) => `unsupported log level: ${String(v)}`,
    (c, v) => (c.logLevel = v),
  ),
  "--retries": integerHandler("--retries", (c, n) => (c.maxRetries = n)),
  "--timeout": integerHandler("--timeout", (c, n) => (c.timeoutMs = n)),
  "--parallel": integerHandler("--parallel", (c, n) => (c.parallelism = n)),
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i += handler(config, argv, i);
  }

  return config;
}

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

