  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  id: string,
  outcome: string,
): void {
  const holding = reserved[id];
  stock[holding.item] = onHand(stock, holding.item) + holding.qty;
  delete reserved[id];
  orders[id] = outcome;
  backfill(stock, reserved, pendingWants, orders, queue);
