interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function onHand(state: State, item: string): number {
  return state.stock[item] === undefined ? 0 : state.stock[item];
}

function addStock(state: State, item: string, qty: number): void {
  state.stock[item] = onHand(state, item) + qty;
}

function takeStock(state: State, item: string, qty: number): void {
  state.stock[item] = onHand(state, item) - qty;
}

function reserve(state: State, id: string, want: Want): void {
  state.reserved[id] = want;
  state.orders[id] = "reserved";
}

function releaseHolding(state: State, id: string): void {
  const holding = state.reserved[id];
  addStock(state, holding.item, holding.qty);
  delete state.reserved[id];
}

function fulfillFromQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHandQty = onHand(state, want.item);
    if (onHandQty >= want.qty) {
      takeStock(state, want.item, want.qty);
      reserve(state, pendingId, want);
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

