  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qty = event.qty as number;
  if (!Number.isInteger(qty) || qty < 1) {
    return "event " + index + ": bad qty";
  }
  if (onHand(state, item) >= qty) {
    takeStock(state, item, qty);
    reserve(state, id, { item, qty });
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
