    return "event " + index + ": bad item";
  }
  const qty = event.qty as number;
  if (!Number.isInteger(qty) || qty < 1) {
    return "event " + index + ": bad qty";
  }
  addStock(state, item, qty);
  fulfillFromQueue(state);
  return undefined;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[id] !== undefined) {
    releaseHolding(state, id);
    state.orders[id] = "expired";
    fulfillFromQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

const HANDLERS: Record<string, (state: State, event: Record<string, unknown>, index: number) => string | undefined> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function parseStock(raw: unknown): Record<string, number> | string {
  if (typeof raw !== "object" || raw === null) {
    return "bad stock";
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(raw as Record<string, unknown>)) {
    const value = (raw as Record<string, unknown>)[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return "bad stock";
    }
    stock[item] = value as number;
  }
  return stock;
}

