interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  stock: Record<string, number>;
  rejected: number;
}

function fillQueue(state: State): void {
  const { queue, pendingWants, stock, reserved, orders } = state;
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const state: State = {
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    stock: {},
    rejected: 0,
  };
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    state.stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const { orders, reserved, pendingWants, queue, stock } = state;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (onHand(stock, event.item) >= (event.qty as number)) {
        stock[event.item] = onHand(stock, event.item) - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        fillQueue(state);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        state.rejected = state.rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        state.rejected = state.rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        state.rejected = state.rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = onHand(stock, event.item) + (event.qty as number);
      fillQueue(state);
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        fillQueue(state);
      } else {
        state.rejected = state.rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected: state.rejected,
    report: buildReport(orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type OrderStatus = "reserved" | "backordered" | "shipped" | "partial" | "cancelled" | "expired";
const STATUSES: OrderStatus[] = [
  "reserved",
  "backordered",
  "shipped",
  "partial",
  "cancelled",
  "expired",
];

interface EventInput {
  type: string;
  id?: string;
  item?: string;
  qty?: number;
}

interface HandlerCtx {
  stock: Record<string, number>;
  orders: Record<string, OrderStatus>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  onHand: (item: string) => number;
  reject: () => void;
}

type HandlerResult = { ok: false; error: string } | { ok: true };

function toNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function toPositiveInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function fillBackorders(ctx: HandlerCtx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    if (want === undefined) {
      ctx.queue.splice(position, 1);
      position--;
      continue;
    }
    const holding = ctx.onHand(want.item);
    if (holding >= want.qty) {
      ctx.stock[want.item] = holding - want.qty;
      ctx.reserved[pendingId] = { ...want };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position--;
    }
  }
}

function releaseReservation(ctx: HandlerCtx, id: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = ctx.onHand(holding.item) + holding.qty;
  delete ctx.reserved[id];
}

function handleOrder(ctx: HandlerCtx, index: number, event: EventInput): HandlerResult {
  if (!toNonEmptyString(event.id) || !toNonEmptyString(event.item)) {
    const bad = !toNonEmptyString(event.id) ? "id" : "item";
    return { ok: false, error: "event " + index + ": bad " + bad };
  }
  if (ctx.orders[event.id] !== undefined) {
    return { ok: false, error: "event " + index + ": duplicate order" };
  }
  if (!toPositiveInteger(event.qty)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const want: Want = { item: event.item, qty: event.qty };
  const available = ctx.onHand(event.item);
  if (available >= want.qty) {
    ctx.stock[event.item] = available - want.qty;
    ctx.reserved[event.id] = { ...want };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { ...want };
    ctx.orders[event.id] = "backordered";
  }
  return { ok: true };
}

function handleCancel(ctx: HandlerCtx, index: number, event: EventInput): HandlerResult {
  if (!toNonEmptyString(event.id)) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id);
    ctx.orders[event.id] = "cancelled";
    fillBackorders(ctx);
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.reject();
  }
  return { ok: true };
}

function handleShip(ctx: HandlerCtx, index: number, event: EventInput): HandlerResult {
  if (!toNonEmptyString(event.id)) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  if (event.qty !== undefined && !toPositiveInteger(event.qty)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const holding = ctx.reserved[event.id];
  if (holding === undefined) {
    ctx.reject();
  } else if (event.qty === undefined || event.qty === holding.qty) {
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "shipped";
  } else if (event.qty < holding.qty) {
    holding.qty = holding.qty - event.qty;
    ctx.orders[event.id] = "partial";
  } else {
    ctx.reject();
  }
  return { ok: true };
}

function handleRestock(ctx: HandlerCtx, index: number, event: EventInput): HandlerResult {
  if (!toNonEmptyString(event.item)) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  if (!toPositiveInteger(event.qty)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  ctx.stock[event.item] = ctx.onHand(event.item) + event.qty;
  fillBackorders(ctx);
  return { ok: true };
}

function handleExpire(ctx: HandlerCtx, index: number, event: EventInput): HandlerResult {
  if (!toNonEmptyString(event.id)) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id);
    ctx.orders[event.id] = "expired";
    fillBackorders(ctx);
  } else {
    ctx.reject();
  }
  return { ok: true };
}

function parseStock(rawStock: unknown): Record<string, number> | null {
  if (typeof rawStock !== "object" || rawStock === null) {
    return null;
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    const value = (rawStock as Record<string, unknown>)[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return null;
    }
    stock[item] = value as number;
  }
  return stock;
}

function runEvents(
  events: EventInput[],
  ctx: HandlerCtx,
  handlers: Record<string, (ctx: HandlerCtx, index: number, event: EventInput) => HandlerResult>
): { ok: false; error: string } | { ok: true } {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = handlers[event.type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const result = handler(ctx, index, event);
    if (!result.ok) {
      return result;
    }
  }
  return { ok: true };
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const stock = parseStock(input.stock);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }

  const orders: Record<string, OrderStatus> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const ctx: HandlerCtx = {
    stock,
    orders,
    reserved,
    pendingWants,
    queue,
    onHand: (item) => stock[item] ?? 0,
    reject: () => {
      rejected++;
    },
  };

  const handlers: Record<string, (ctx: HandlerCtx, index: number, event: EventInput) => HandlerResult> = {
    order: handleOrder,
    cancel: handleCancel,
    ship: handleShip,
    restock: handleRestock,
    expire: handleExpire,
  };

  const run = runEvents(input.events as EventInput[], ctx, handlers);
  if (!run.ok) {
    return run;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

function statusCounts(orders: Record<string, OrderStatus>): Record<OrderStatus, number> {
  const counts: Record<OrderStatus, number> = { reserved: 0, backordered: 0, shipped: 0, partial: 0, cancelled: 0, expired: 0 };
  for (const id of Object.keys(orders)) {
    counts[orders[id]]++;
  }
  return counts;
}

function buildReport(orders: Record<string, OrderStatus>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

