export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const SUPPORTED_CURRENCIES = new Set(["USD", "EUR"]);

function isEmpty(value: string): boolean {
  return value.length === 0;
}

function validateId(errors: string[], value: string, label: string): void {
  if (isEmpty(value)) {
    errors.push(`${label} is required`);
  }
}

function validateOrderItems(errors: string[], items: OrderItem[]): void {
  if (items.length === 0) {
