files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function err(index: number, message: string): string {
  return "event " + index + ": " + message;
}

function readId(event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return err(index, "bad id");
  }
  return event.id;
}

function readQty(event: Record<string, unknown>, index: number): number | undefined {
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return err(index, "bad qty");
  }
  return event.qty as number;
}

function readItem(event: Record<string, unknown>, index: number): string | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return err(index, "bad item");
  }
  return event.item;
}

function fulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position--;
    }
  }
}

function releaseAndRefill(ctx: Context, holding: Want): void {
  ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
  fulfillQueue(ctx);
}

function handleOrder(ctx: Context, event: Record<string, unknown>, index: number): string | undefined {
  const id = readId(event, index);
  if (id === undefined) return id;
  if (ctx.orders[id] !== undefined) return err(index, "duplicate order");
  const item = readItem(event, index);
  if (item === undefined) return item;
  const qty = readQty(event, index);
  if (qty === undefined) return qty;
  const available = ctx.stock[item] ?? 0;
  if (available >= qty) {
    ctx.stock[item] = available - qty;
    ctx.reserved[id] = { item, qty };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
  return undefined;
}

function handleCancel(ctx: Context, event: Record<string, unknown>, index: number): string | undefined {
  const id = readId(event, index);
  if (id === undefined) return id;
  if (ctx.reserved[id] !== undefined) {
    const holding = ctx.reserved[id];
    delete ctx.reserved[id];
    ctx.orders[id] = "cancelled";
    releaseAndRefill(ctx, holding);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected++;
  }
  return undefined;
}

type ShipAction = (ctx: Context, id: string, holding: Want, qty: number) => void;

function shipFull(ctx: Context, id: string): void {
  delete ctx.reserved[id];
  ctx.orders[id] = "shipped";
}

function shipPartial(ctx: Context, id: string, holding: Want, qty: number): void {
  holding.qty = holding.qty - qty;
  ctx.orders[id] = "partial";
}

function shipRejected(ctx: Context): void {
  ctx.rejected++;
}

const SHIP_ACTIONS: Record<number, ShipAction> = {
  [-1]: (ctx, id, holding, qty) => shipPartial(ctx, id, holding, qty),
  [0]: (ctx, id) => shipFull(ctx, id),
  [1]: (ctx) => shipRejected(ctx),
};

function handleShip(ctx: Context, event: Record<string, unknown>, index: number): string | undefined {
  const id = readId(event, index);
  if (id === undefined) return id;
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return err(index, "bad qty");
  }
  const holding = ctx.reserved[id];
  if (holding === undefined) {
    ctx.rejected++;
    return undefined;
  }
  const qty = (event.qty as number | undefined) ?? holding.qty;
  const act = SHIP_ACTIONS[Math.sign(qty - holding.qty)];
  act(ctx, id, holding, qty);
  return undefined;
}

function handleRestock(ctx: Context, event: Record<string, unknown>, index: number): string | undefined {
  const item = readItem(event, index);
  if (item === undefined) return item;
  const qty = readQty(event, index);
  if (qty === undefined) return qty;
  ctx.stock[item] = (ctx.stock[item] ?? 0) + qty;
  fulfillQueue(ctx);
  return undefined;
}

function handleExpire(ctx: Context, event: Record<string, unknown>, index: number): string | undefined {
  const id = readId(event, index);
  if (id === undefined) return id;
  if (ctx.reserved[id] !== undefined) {
    const holding = ctx.reserved[id];
    delete ctx.reserved[id];
    ctx.orders[id] = "expired";
    releaseAndRefill(ctx, holding);
  } else {
    ctx.rejected++;
  }
  return undefined;
}

type EventHandler = (ctx: Context, event: Record<string, unknown>, index: number) => string | undefined;

const HANDLERS: Record<string, EventHandler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function buildContext(rawStock: Record<string, unknown>): Context | null {
  const ctx: Context = {
    stock: {},
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return null;
    }
    ctx.stock[item] = rawStock[item] as number;
  }
  return ctx;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const ctx = buildContext(input.stock as Record<string, unknown>);
  if (ctx === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: err(index, "malformed") };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: err(index, "bad type") };
    }
    const error = handle(ctx, event, index);
    if (error !== undefined) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

