const bvals = [-1,0,49,50,199,200,599,600,899,900,1000,1500];
check('boundaries', {readings:bvals.map((v,i)=>R('Ch'+i,'mV',v,i))});
check('agg', {readings:[
  R('X','mV',100,1),R('X','mV',900,2),R('X','mV',-5,3),R('X','mV',450,4),
  R('Y','V',0.7,5),R('Y','V',0.25,6)]});
check('loaded+order', {readings:[R('Z','mV',650,1),R('Z','mV',850,2),R('Z','mV',600,3)]});
// separate enumerate comparisons for classifySignal
let cFail=0;
for (let v=-100; v<=1100; v++) {
  const a=old.classifySignal(v), b=nw.classifySignal(v);
  if(a!==b){cFail++; if(cFail<5)console.log('classify mismatch',v,a,b);}
}
if(cFail) console.log('classifySignal mismatches:', cFail);
else console.log('classifySignal matches all -100..1100');

if (failures===0 && cFail===0) console.log('ALL BEHAVIOR MATCHES');
else { console.log('FAILURES:', failures); process.exit(1); }

